pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that implements transferFrom and approve
        // We only need addresses, not actual token logic; the buggy version calls approve with wrong args
        // Note: The reference version calls transferFrom(from, to, amount) — this succeeds
        // The buggy version calls approve(from, to) — this expects (spender, amount) and will revert

        vm.deal(address(0x1), 1 ether);

        // We'll use a minimal contract that reverts on wrong function signature
        // But simpler: we can just use an EOA as caddress — calls will succeed regardless
        // Actually the difference: reference calls transferFrom, bug calls approve
        // If caddress is an EOA, both calls succeed (no revert) so cannot distinguish
        // We need a contract that reverts if approve is called with wrong parameters
        // So let's deploy a simple contract that implements fallback to revert

        // Better: Use a contract that has a transferFrom but no approve
        // Then reference succeeds, bug reverts

        // Deploy a mock that only accepts transferFrom selector
        address mock = address(new MockToken());

        // Prepare arrays
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;

        // Try calling transfer; the reference (unmodified) would succeed, the buggy would revert
        bool ok;
        try c.transfer(address(0x1), mock, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Reference should succeed, bug should fail");
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    fallback() external {
        revert("unexpected call");
    }
}

