pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that reverts on the second transferFrom
        RevertingToken token = new RevertingToken();
        address alice = address(0x123);
        address bob = address(0x456);
        address charlie = address(0x789);

        address[] memory tos = new address[](2);
        tos[0] = bob;
        tos[1] = charlie;
        uint[] memory values = new uint[](2);
        values[0] = 10;
        values[1] = 20;

        // Call transfer - reference reverts, bug does not
        bool ok;
        try c.transfer(alice, address(token), tos, values) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: reverts => ok == false; Bug: returns true => ok == true
        assertTrue(!ok);
    }
}

contract RevertingToken {
    uint callCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        if (callCount == 2) {
            revert("fail");
        }
        return true;
    }
}
